package com.foodie.controller;
import com.foodie.dto.ApiDtos.*; import com.foodie.service.CartService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/customers/{customerId}/cart") public class CartController {private final CartService service;public CartController(CartService s){service=s;}@GetMapping CartView get(@PathVariable Long customerId){return service.get(customerId);}@PostMapping("/items") CartView add(@PathVariable Long customerId,@Valid @RequestBody CartItemRequest r){return service.add(customerId,r);}@DeleteMapping ResponseEntity<Void> clear(@PathVariable Long customerId){service.clear(customerId);return ResponseEntity.noContent().build();}}
